import{_ as s,C as n,o as l,c as e,j as t,E as o,a as r,a3 as d}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"n":5,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":13,"title":"Muloqot va jamoada ishlash ko'nikmalari","lead":"Yaxshi kod yetarli emas: uni boshqalarga tushuntirish, fikr almashish va birga ishlash kerak. Bugun muloqot va jamoa ko'nikmalarini mashq qilamiz.","link":"/mentor/11-sinf/hafta-05/dars-1","slide":"/slaydlar/11-sinf/hafta-05/dars-1.html","test":"/slaydlar/11-sinf/hafta-05/dars-1-test.html"},{"g":14,"title":"Liderlik, mas'uliyat va vaqtni boshqarish","lead":"Lider bo'lish uchun jamoa kerak emas: o'z ishingizga egalik qilish va vaqtni boshqarishdan boshlanadi. Bugun mas'uliyat, ustuvorlik va fokusni mashq qilamiz.","link":"/mentor/11-sinf/hafta-05/dars-2","slide":"/slaydlar/11-sinf/hafta-05/dars-2.html","test":"/slaydlar/11-sinf/hafta-05/dars-2-test.html"},{"g":15,"title":"ORALIQ NAZORAT","lead":"Bugun oraliq nazorat: I bob bo'yicha amaliy topshiriq. Qoidalarni, mavzular xaritasini va baholash mezonlarini bilib oling.","link":"/mentor/11-sinf/hafta-05/dars-3","slide":"/slaydlar/11-sinf/hafta-05/dars-3.html","test":"/slaydlar/11-sinf/hafta-05/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/11-sinf/hafta-05/index.md","filePath":"mentor/11-sinf/hafta-05/index.md"}`),h={name:"mentor/11-sinf/hafta-05/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},_={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function g(k,a,q,y,v,c){const i=n("Icon");return l(),e("div",null,[t("div",u,[t("h2",m,[o(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h2 id="_13-dars-uchun-muloqot-va-jamoada-ishlash" tabindex="-1">13-dars uchun (Muloqot va jamoada ishlash) <a class="header-anchor" href="#_13-dars-uchun-muloqot-va-jamoada-ishlash" aria-label="Permalink to &quot;13-dars uchun (Muloqot va jamoada ishlash)&quot;">​</a></h2><p><strong>1-topshiriq: «PR shabloni va mini-retro»</strong></p><ol><li>Portfolio repozitoriyingizda <code>.github/pull_request_template.md</code> yozing: <code>What</code>, <code>Why</code>, <code>How</code>, <code>Keyingi qadam va deadline</code>.</li><li>Oxirgi PR yoki xabaringizni kontekst, tuzilma, yakun bo&#39;yicha qayta yozing (oldingi va keyingi variantni <code>docs/muloqot.md</code> ga qo&#39;ying).</li><li>O&#39;z haftangiz uchun mini-retro yozuvini tuzing: 1 ta ishlagan, 1 ta to&#39;sqinlik, 2 ta SMART action (owner va deadline bilan).</li></ol><p><strong>Kutiladigan natija:</strong> PR shabloni, qayta yozilgan xabar va retro yozuvi.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h2 id="_14-dars-uchun-liderlik-mas-uliyat-vaqt" tabindex="-1">14-dars uchun (Liderlik, mas&#39;uliyat, vaqt) <a class="header-anchor" href="#_14-dars-uchun-liderlik-mas-uliyat-vaqt" aria-label="Permalink to &quot;14-dars uchun (Liderlik, mas&#39;uliyat, vaqt)&quot;">​</a></h2><p><strong>2-topshiriq: «Delegatsiya va haftalik reja»</strong></p><ol><li><code>docs/delegatsiya.md</code> da bitta vazifani 5 qismli delegatsiya shaklida yozing: natija, cheklov, resurs, erkinlik hududi, checkpoint.</li><li>Shu faylda kechikish haqida erta signal yozing: fakt, sabab, taklif, deadline.</li><li>Keyingi haftangiz uchun 3 ta «katta tosh» va 6 vazifali Eisenhower matritsasini tuzing.</li><li>I bob mavzulari (1–14-dars) ichidan 3 ta kuchsiz mavzuni belgilab, har biriga 1 ta takrorlash qadamini yozing.</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;liq delegatsiya xabari, erta signal, matritsa va takrorlash rejasi.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h2 id="_15-dars-uchun-oraliq-nazoratdan-keyin" tabindex="-1">15-dars uchun (Oraliq nazoratdan keyin) <a class="header-anchor" href="#_15-dars-uchun-oraliq-nazoratdan-keyin" aria-label="Permalink to &quot;15-dars uchun (Oraliq nazoratdan keyin)&quot;">​</a></h2><p><strong>3-topshiriq: «Xatolar ustida ishlash»</strong></p><ol><li>Mentor bilan tahlildan keyin eng ko&#39;p ball yo&#39;qotilgan qismni qayta bajaring.</li><li><code>xatolar.md</code> ga 3 ta xatoni va har birini qanday tuzatganingizni yozing.</li></ol><p><strong>Kutiladigan natija:</strong> tuzatilgan kod va <code>xatolar.md</code>.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>13-darsda xabarlarda kontekst, tuzilma va yakun borligini, action-itemlarda owner va deadline yozilganini tekshiring. 14-darsda delegatsiya matni «uloqtirish» emas, aniq natija va checkpointlarga ega ekanini ko&#39;ring. Nazorat natijalarini <code>baholash.md</code> ga kiriting va xatolar ustida ishlash vazifasini 6-hafta boshida qabul qiling.</p>',18))]),t("div",_,[t("h2",b,[o(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p>Bitta o&#39;quvchi uchun shablon. Maqsad: haftalar bo&#39;yicha o&#39;sish dinamikasini kuzatish. Har hafta shu shablon nusxalanib, «Dinamika» jadvaliga bitta qator qo&#39;shiladi.</p><p><strong>O&#39;quvchi:</strong> ____________________ <strong>Guruh/sinf:</strong> 11-sinf <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" tabindex="-1">Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim) <a class="header-anchor" href="#shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" aria-label="Permalink to &quot;Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim)&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><p>Dasturdagi mezonlar: mavzu bo&#39;yicha tasavvurga ega bo&#39;lish; mavzu mohiyatini tushunish va aytib bera olish; bilimni amalda qo&#39;llash; ijodiy fikrlash va xulosa chiqarish; mustaqil ish bajarish.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mohiyatni tushunadi va aytib bera oladi (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq, mustaqil bajarilgan</td><td>30</td></tr><tr><td>Ish sifati: aniqlik, tuzilma, haqiqiy misollar</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan va o&#39;z vaqtida topshirilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="_13-dars-muloqot-va-jamoada-ishlash-ko-nikmalari" tabindex="-1">13-dars. Muloqot va jamoada ishlash ko&#39;nikmalari <a class="header-anchor" href="#_13-dars-muloqot-va-jamoada-ishlash-ko-nikmalari" aria-label="Permalink to &quot;13-dars. Muloqot va jamoada ishlash ko&#39;nikmalari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>Faol tinglash bosqichlari; «I-xabar» va SBI; yozma xabarning 3 mezoni; psixologik xavfsizlik</td><td></td></tr><tr><td>Amaliyot /30</td><td>Qayta ifodalash va aniqlashtiruvchi savol; «I-xabar» yozish; PR tavsifi (What/Why/How)</td><td></td></tr><tr><td>Ish sifati /20</td><td>Xabarda kontekst, tuzilma, yakun; action-itemda owner va deadline</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>pull_request_template.md</code>, qayta yozilgan xabar va mini-retro yozuvi topshirilgan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_14-dars-liderlik-mas-uliyat-va-vaqtni-boshqarish" tabindex="-1">14-dars. Liderlik, mas&#39;uliyat va vaqtni boshqarish <a class="header-anchor" href="#_14-dars-liderlik-mas-uliyat-va-vaqtni-boshqarish" aria-label="Permalink to &quot;14-dars. Liderlik, mas&#39;uliyat va vaqtni boshqarish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>Uch liderlik uslubi; delegatsiya tarkibi; erta signal 4 qismi; SMART va Eisenhower</td><td></td></tr><tr><td>Amaliyot /30</td><td>SMART maqsad; Eisenhower matritsasi; delegatsiya va erta signal matni</td><td></td></tr><tr><td>Ish sifati /20</td><td>Matnlarda aniq raqam, muddat va owner; matritsada asosli joylashtirish</td><td></td></tr><tr><td>Uyga vazifa /20</td><td>Delegatsiya xabari, haftalik reja va 3 ta kuchsiz mavzu belgilangan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_15-dars-oraliq-nazorat-i-bob" tabindex="-1">15-dars. ORALIQ NAZORAT (I bob) <a class="header-anchor" href="#_15-dars-oraliq-nazorat-i-bob" aria-label="Permalink to &quot;15-dars. ORALIQ NAZORAT (I bob)&quot;">​</a></h2><p>Topshiriq va namunaviy yechim: <code>dars-3.md</code>, 4-bo&#39;lim.</p><table tabindex="0"><thead><tr><th>Qism</th><th>Nimaga qaraladi</th><th>Max</th><th>Ball</th></tr></thead><tbody><tr><td>A. Clean Code, SOLID</td><td>Ma&#39;noli nomlar, SRP, sehrli satrlar va <code>== True</code> yo&#39;q</td><td>20</td><td></td></tr><tr><td>B. Observer</td><td><code>EventBus</code>, ikki hodisa, xato izolyatsiyasi</td><td>25</td><td></td></tr><tr><td>C. REST/JSON</td><td><code>make_error</code>, <code>paginate</code>, <code>sanitize_user</code>, kamida 4 test</td><td>25</td><td></td></tr><tr><td>D. Git va PR</td><td>Tarmoq nomi, 3 semantik commit, What/Why/How</td><td>20</td><td></td></tr><tr><td>E. Soft skills</td><td>Eisenhower asosi, «I-xabar»</td><td>10</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td><strong>100</strong></td><td></td></tr></tbody></table><p>Baho: ____ Og&#39;zaki tahlil izohi: ____________________</p><hr><h2 id="_5-hafta-yakuni-o-sish-dinamikasi" tabindex="-1">5-hafta yakuni: o&#39;sish dinamikasi <a class="header-anchor" href="#_5-hafta-yakuni-o-sish-dinamikasi" aria-label="Permalink to &quot;5-hafta yakuni: o&#39;sish dinamikasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hafta</th><th>Darslar</th><th>O&#39;rtacha ball</th><th>Baho</th><th>Asosiy yutuq / Aniqlangan bo&#39;shliq</th></tr></thead><tbody><tr><td>1-hafta</td><td>1–3 (SDLC, Git)</td><td></td><td></td><td></td></tr><tr><td>2-hafta</td><td>4–6 (Branching, PR)</td><td></td><td></td><td></td></tr><tr><td>3-hafta</td><td>7–9 (SOLID, Patterns)</td><td></td><td></td><td></td></tr><tr><td>4-hafta</td><td>10–12 (Observer, REST, JSON)</td><td></td><td></td><td></td></tr><tr><td>5-hafta</td><td>13–15 (Soft skills, Oraliq nazorat)</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Mentor tavsiyasi:</strong> I bob yakunlandi: texnik mavzular (Git, Clean Code, SOLID, patternlar, REST/JSON) va soft skills nazoratdan o&#39;tdi. 6-haftadan II bob boshlanadi: Unix/Linux, SSH va Nginx. Nazorat natijasida aniqlangan kuchsiz mavzularni (A–E qismlar bo&#39;yicha) 6-haftaning birinchi darsida qisqa takrorlang.</p>',23))])])}const p=s(h,[["render",g]]);export{z as __pageData,p as default};
